<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription } from '@/components/ui/dialog'
import { Tabs,TabsList,TabsTrigger } from '@/components/ui/tabs'
import { Select,SelectTrigger,SelectValue,SelectContent,SelectGroup,SelectItem } from '@/components/ui/select'
import { knowledgeTruncated,knowledgeErrors,knowledgeDocs,knowledgeOpen,knowledgeTab,tagFilter,loadKnowledge,liveKnowledge,resolveKnowledge,linkProblem,filterByTags,type KnowledgeDoc } from '@/services/knowledge'
import { useWorkbench } from '@/stores/workbench'
import { message } from '@/services/api'
import { setDocumentField } from '@/services/frontmatter'
const store=useWorkbench(),loading=ref(false),error=ref(''),query=ref(''),included=ref<string[]>([]),excluded=ref<string[]>([]),mode=ref('all'),graphMode=ref('workspace')
const docs=computed(()=>{void knowledgeDocs.value;return liveKnowledge()}),tags=computed(()=>[...new Set(docs.value.flatMap(d=>d.tags))].sort()),active=computed(()=>docs.value.find(d=>d.workspaceId===store.active?.workspaceId&&d.path===store.active.path))
const backlinks=computed(()=>active.value?docs.value.filter(d=>d.links.some(l=>resolveKnowledge(d,l.target,l.wiki)?.path===active.value?.path&&d.workspaceId===active.value!.workspaceId)):[])
const related=computed(()=>active.value?docs.value.filter(d=>d.path!==active.value!.path||d.workspaceId!==active.value!.workspaceId).map(d=>({doc:d,score:d.tags.filter(t=>active.value!.tags.includes(t)).length+(backlinks.value.includes(d)?2:0)+(active.value!.links.some(l=>resolveKnowledge(active.value!,l.target,l.wiki)?.path===d.path&&d.workspaceId===active.value!.workspaceId)?2:0)})).filter(d=>d.score).sort((a,b)=>b.score-a.score).map(x=>x.doc):[])
const filtered=computed(()=>docs.value.filter(d=>(d.path+' '+d.tags.join(' ')).toLowerCase().includes(query.value.toLowerCase())&&filterByTags(d,included.value,excluded.value,mode.value)))
const broken=computed(()=>docs.value.flatMap(d=>d.links.map(l=>({doc:d,link:l,problem:linkProblem(d,l)})).filter(x=>x.problem)))
const graphDocs=computed(()=>graphMode.value==='current'&&active.value?docs.value.filter(d=>(d.workspaceId===active.value!.workspaceId&&d.path===active.value!.path)||backlinks.value.some(x=>x.workspaceId===d.workspaceId&&x.path===d.path)||active.value!.links.some(l=>{const target=resolveKnowledge(active.value!,l.target,l.wiki);return target?.workspaceId===d.workspaceId&&target.path===d.path})):active.value?docs.value.filter(d=>d.workspaceId===active.value!.workspaceId):docs.value)
const nodes=computed(()=>graphDocs.value.slice(0,120).map((d,i,a)=>({doc:d,x:300+235*Math.cos(i*2*Math.PI/a.length),y:260+200*Math.sin(i*2*Math.PI/a.length)})))
const edges=computed(()=>nodes.value.flatMap(n=>n.doc.links.flatMap(l=>{const target=resolveKnowledge(n.doc,l.target,l.wiki);const to=nodes.value.find(x=>x.doc===target);return to?[{from:n,to}]:[]})))
const recent=computed(()=>store.preferences.recentFiles.flatMap(r=>{const d=docs.value.find(d=>d.workspaceId===r.workspaceId&&d.path===r.path);return d?[d]:[]}).slice(0,8)),favorites=computed(()=>docs.value.filter(d=>store.preferences.favorites.some(f=>f.workspaceId===d.workspaceId&&f.path===d.path)))
async function refresh(){loading.value=true;error.value='';try{await loadKnowledge(true)}catch(e){error.value=message(e)}finally{loading.value=false}}
watch(knowledgeOpen,open=>{if(open){included.value=tagFilter.value?[tagFilter.value]:[];tagFilter.value='';void refresh()}})
async function open(d:KnowledgeDoc){await store.open(d.workspaceId,d.path);knowledgeOpen.value=false}
function toggle(list:string[],tag:string){const i=list.indexOf(tag);i<0?list.push(tag):list.splice(i,1)}
function status(value:string){if(!store.active)return;try{store.change(store.active,setDocumentField(store.active.text,'status',value),'metadata');store.active.generation++}catch(e){error.value=message(e)}}
</script>
<template><Dialog v-model:open="knowledgeOpen"><DialogContent class="flex h-[min(800px,90dvh)] flex-col sm:max-w-5xl"><DialogHeader><DialogTitle>工作区知识与文档</DialogTitle><DialogDescription>浏览文档、标签与链接关系。索引只读取本地 Markdown 文件。</DialogDescription></DialogHeader><Tabs v-model="knowledgeTab"><TabsList class="flex h-auto flex-wrap"><TabsTrigger value="home">项目首页</TabsTrigger><TabsTrigger value="tags">标签筛选</TabsTrigger><TabsTrigger value="backlinks">反向链接</TabsTrigger><TabsTrigger value="related">相关文档</TabsTrigger><TabsTrigger value="broken">断链检查</TabsTrigger><TabsTrigger value="graph">关系图</TabsTrigger><TabsTrigger value="syntax">语法说明</TabsTrigger></TabsList></Tabs><div class="flex gap-2"><Input v-model="query" aria-label="筛选文档" placeholder="搜索文件名或标签…"/><Button variant="outline" :disabled="loading" @click="refresh">刷新索引</Button></div><p v-if="loading" role="status">正在读取本地文档…</p><p v-if="error" role="alert" class="text-sm text-destructive">{{error}}</p><p v-if="knowledgeTruncated" class="text-xs text-muted-foreground">部分大文件或超出索引上限的文档未加载；当前结果不代表完整工作区。</p><p v-for="problem in knowledgeErrors" :key="problem" role="alert" class="text-xs text-destructive">{{problem}}</p><div class="min-h-0 flex-1 overflow-auto">
<template v-if="knowledgeTab==='home'"><div class="mb-6 flex flex-wrap items-center gap-2"><span class="text-sm">当前文档状态</span><Button v-for="s in ['草稿','进行中','已完成','归档']" :key="s" size="sm" :variant="active?.status===s?'default':'outline'" :disabled="!store.active" @click="status(s)">{{s}}</Button></div><div class="grid gap-6 sm:grid-cols-2"><section v-for="group in [{title:'最近文档',rows:recent},{title:'收藏文档',rows:favorites},{title:'相关笔记',rows:related},{title:'待办文档',rows:docs.filter(d=>/^- \[ \]/m.test(d.text)||d.status==='进行中')}]" :key="group.title"><h3 class="mb-2 font-semibold">{{group.title}}</h3><Button v-for="d in group.rows.slice(0,12)" :key="d.workspaceId+d.path" variant="ghost" class="w-full justify-start truncate" :title="d.path" @click="open(d)">{{d.path}}</Button><p v-if="!group.rows.length" class="text-sm text-muted-foreground">暂无文档。</p></section></div></template>
<template v-else-if="knowledgeTab==='tags'"><div class="mb-4 flex flex-wrap items-center gap-3 text-sm"><label class="flex items-center gap-2">组合方式 <Select v-model="mode"><SelectTrigger aria-label="组合方式"><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectItem value="all">全部满足</SelectItem><SelectItem value="any">满足任意</SelectItem></SelectGroup></SelectContent></Select></label><Button variant="ghost" size="sm" @click="included=[];excluded=[]">清空筛选</Button></div><div class="mb-3 flex flex-wrap gap-2"><Button v-for="tag in tags" :key="tag" size="sm" :variant="included.includes(tag)?'default':'outline'" @click="toggle(included,tag)"><span v-if="store.preferences.tagColors[tag]" class="mr-1 size-2 rounded-full" :style="{backgroundColor:store.preferences.tagColors[tag]}"/>{{tag}}</Button></div><p class="mb-2 text-xs text-muted-foreground">排除标签</p><div class="mb-4 flex flex-wrap gap-2"><Button v-for="tag in tags" :key="tag" size="sm" :variant="excluded.includes(tag)?'destructive':'ghost'" @click="toggle(excluded,tag)">{{tag}}</Button></div><p class="mb-2 text-sm text-muted-foreground">{{filtered.length}} 篇文档</p><Button v-for="d in filtered" :key="d.workspaceId+d.path" variant="ghost" class="w-full justify-start" @click="open(d)">{{d.path}}<span class="ml-auto text-xs">{{d.tags.join(' · ')}}</span></Button></template>
<template v-else-if="knowledgeTab==='backlinks'||knowledgeTab==='related'"><p class="mb-3 text-sm text-muted-foreground">{{active?.path||'请先打开文档'}} · {{knowledgeTab==='backlinks'?'哪些文档引用了当前文档':'按共同标签与链接关联排列'}}</p><Button v-for="d in knowledgeTab==='backlinks'?backlinks:related" :key="d.workspaceId+d.path" variant="ghost" class="w-full justify-start" @click="open(d)">{{d.path}}</Button><p v-if="!(knowledgeTab==='backlinks'?backlinks:related).length" class="text-sm text-muted-foreground">暂无关联文档。</p></template>
<template v-else-if="knowledgeTab==='broken'"><p v-if="!broken.length" class="text-sm text-primary">没有发现失效文档或章节链接。</p><Button v-for="(row,i) in broken" :key="i" variant="ghost" class="h-auto w-full flex-col items-start gap-1 py-3" @click="open(row.doc)"><span>{{row.doc.path}} → {{row.link.target}}</span><span class="text-xs text-destructive">{{row.problem}}</span></Button></template>
<template v-else-if="knowledgeTab==='graph'"><div class="mb-3 flex items-center justify-between gap-3"><p class="text-xs text-muted-foreground">显示前 120 篇文档，点击节点打开文档。</p><Select v-model="graphMode"><SelectTrigger aria-label="关系图范围" class="shrink-0"><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectItem value="workspace">当前工作区</SelectItem><SelectItem value="current">当前文档及直接关联</SelectItem></SelectGroup></SelectContent></Select></div><svg viewBox="0 0 600 520" class="mx-auto w-full max-w-3xl"><line v-for="(e,i) in edges" :key="i" :x1="e.from.x" :y1="e.from.y" :x2="e.to.x" :y2="e.to.y" class="stroke-border"/><g v-for="n in nodes" :key="n.doc.workspaceId+n.doc.path" role="button" tabindex="0" :aria-label="n.doc.path" class="cursor-pointer" @click="open(n.doc)" @keydown.enter="open(n.doc)"><title>{{n.doc.path}}</title><circle :cx="n.x" :cy="n.y" r="7" class="fill-primary"/><text :x="n.x+10" :y="n.y+4" class="fill-foreground text-[9px]">{{n.doc.path.split('/').pop()}}</text></g></svg></template>
<div v-else class="space-y-4 text-sm leading-7"><p>支持：标题、列表、任务、引用、表格、围栏代码、脚注、链接、图片、行内与块公式、Mermaid 图表、提示块与双向链接。</p><p>双向链接：[[文档]]、[[文件夹/文档#章节|显示文本]]。同名文档请填写目录路径。</p><p>公式：$a+b$；块公式用单独两行 $$ 包围。图表：使用语言为 mermaid 的围栏代码块。</p><p>提示块：引用段落以 [!NOTE]、[!TIP]、[!IMPORTANT]、[!WARNING] 或 [!CAUTION] 开头。</p><p>脚注：正文 [^1]，文末 [^1]: 注释内容。预览支持跳转与返回。</p><p>HTML 预览会过滤脚本、内联样式和嵌入内容，磁盘原文保持不变。未知语法保留原文；公式和图表失败时显示原因与源码。</p><p>章节可在阅读预览中折叠。公式与图表建议使用分屏检查，源码视图完整保留语法。</p></div>
</div></DialogContent></Dialog></template>
